INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سفل:ibn_manzur_lisan_arab', 'سفل', 'd535fefc0d4afa1e990eadb5ce', 'السُّفْلُ والسِّفْلُ والسُّفُولُ والسَّفَال والسُّفَالَة، بِالضَّمِّ. نقيضُ العُلْوِ', 'the opposite of height', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_4629f6cd26204994', '1876', 3, 'blk_lsn_f51eb79fd12b973c', 0, NULL, 'Marker: head gloss. Reading: lowness.', 'high', 'active');
