INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سفل:qamus_muhit', 'سفل', 'd535fefc0d4afa1e990eadb5ce', 'السُّفْلُ والسُّفولُ والسُّفالَةُ، بضمهِنَّ، والسِّفْلُ والسِّفْلَةُ، بكسرهما، والسَّفالُ، بالفتح: نَقيضُ العُلْوِ', 'the opposite of height', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_4a54be235b23fc7e', NULL, NULL, 'blk_qms_fbcfd987f225c1be', 0, NULL, 'Marker: head gloss. Reading: lowness.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سفل:zabidi_taj_arus', 'سفل', 'd535fefc0d4afa1e990eadb5ce', 'والسُّفْلَى: نَقِيضُ العُلْيَا، والأَسْفَلُ: نَقَيضُ الأَعْلَى', 'lower is the opposite of higher', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_64cecac26a932218', '204', 29, 'blk_taj_5fc6f91c41a6ea9b', 0, NULL, 'Marker: Qāmūs gloss. Reading: lowness.', 'high', 'active');
