INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سهل:fayyumi_misbah_munir', 'سهل', '60fb3e00fa544bad14fe82f7a7', 'ابْنُ فَارِسٍ السَّهْلُ خِلَافُ الْحَزْنِ', 'the opposite of rough ground', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_d9d85b4ce8eb5481', '1497', NULL, 'blk_msb_74c6cda8eea0d868', 0, NULL, 'Marker: quoted gloss (Ibn Fāris). Reading: smooth ground.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سهل:qamus_muhit', 'سهل', '60fb3e00fa544bad14fe82f7a7', 'السَّهْلُ، وككَتِفٍ: كلُّ شيءٍ إلى اللين', 'anything leaning toward softness', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_1a690d8484eb1f27', NULL, NULL, 'blk_qms_93d64a109f87435a', 0, NULL, 'Marker: Qāmūs gloss. Reading: softness.', 'high', 'active');
