INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سهل:lane_lexicon', 'سهل', '60fb3e00fa544bad14fe82f7a7', 'It was, or became, smooth or soft, plain or level, or smooth and soft', 'it became smooth, soft or level', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_3ef7da8ad66f9c1b', '1452', NULL, 'blk_lane_76fd99c283968dc7', 0, NULL, 'Marker: first sense A1. Reading: smoothness.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: softness.', updated_at = datetime('now') WHERE id = 'ASL:سهل:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:سهل:jawhari_sihah' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'سهل' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:سهل:jawhari_sihah' AND status <> 'rejected');
